export function documentationExecutableSelectors(source,bytes,root){
 const tree=ts.createSourceFile(source,bytes,ts.ScriptTarget.Latest,true);assert(!tree.parseDiagnostics.length,`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; source syntax`);
 reviewedSdkGeneratorImport(source,bytes,tree); // purpose evidence only; immutable selector/facts checks still follow
 const selected=new Set(),sinkLines=new Set(root?serializedOutputSinkSites(root,source,[source]).map(site=>site.line):[]),capabilities=new Set(['eval','Function','spawnSync','spawn','execFile','execFileSync','exec','execSync']);
 for(const statement of tree.statements){
  if(ts.isImportDeclaration(statement)){selected.add(statement.getText(tree));if(['node:child_process','child_process'].includes(statement.moduleSpecifier.text)){if(statement.importClause?.namedBindings&&ts.isNamedImports(statement.importClause.namedBindings))for(const item of statement.importClause.namedBindings.elements)capabilities.add(item.name.text);if(statement.importClause?.namedBindings&&ts.isNamespaceImport(statement.importClause.namedBindings))for(const name of ['spawnSync','spawn','execFile','execFileSync','exec','execSync'])capabilities.add(statement.importClause.namedBindings.name.text+'.'+name);}}
  if(ts.isExportDeclaration(statement)||ts.isExportAssignment(statement)||statement.modifiers?.some(modifier=>modifier.kind===ts.SyntaxKind.ExportKeyword))selected.add(statement.getText(tree));
 }
 function visit(node){
  if(ts.isCallExpression(node)||ts.isNewExpression(node)){const at=tree.getLineAndCharacterOfPosition(node.getStart(tree)).line+1;if(sinkLines.has(at)||capabilities.has(node.expression.getText(tree))||node.expression.kind===ts.SyntaxKind.ImportKeyword)selected.add(node.getText(tree));}
  if(ts.isIdentifier(node)&&capabilities.has(node.text)&&!(ts.isImportSpecifier(node.parent)||ts.isImportClause(node.parent))){if(!ts.isCallExpression(node.parent)||node.parent.expression!==node)selected.add(node.parent.getText(tree));}
  if(ts.isExpressionStatement(node)&&ts.isSourceFile(node.parent))selected.add(node.getText(tree));
  ts.forEachChild(node,visit);
 }
 visit(tree);return [...selected].sort().map(expression=>({expression}));
}
// Bind literal child/source acquisitions independently of the parent's own
// operations. A changed helper must not inherit yesterday's consumer role.
function assertReviewedVariableDocumentationChild(source,bytes,tree,acquire) {
 const recipe=reviewedVariableDocumentationChildren[source];
 if(!recipe)return;
 const fail=detail=>assert.fail(`DOCUMENTATION_TOOL_OUTPUT_ROLE_UNQUALIFIED: ${source}; finite variable child custody: ${detail}`);
 const hash=text=>createHash('sha256').update(text).digest('hex');
 if(hash(assertReviewedVariableDocumentationChild.toString())!==recipe.guardDefinitionSha256)fail('guard definition changed');
 if(hash(bytes)!==recipe.sourceSha256)fail('owning source changed');
 if(tree.parseDiagnostics.length)fail('source syntax');
 for(const syntax of recipe.definingSyntax){
  if(tree.statements.filter(node=>node.getText(tree)===syntax).length!==1)fail('selected import/root definition changed');
 }
 const owners=tree.statements.filter(node=>ts.isFunctionDeclaration(node)&&node.name?.text===recipe.owner);
 if(owners.length!==1||!owners[0].body)fail('owner missing or ambiguous');
 const owner=owners[0];
 if(hash(owner.getText(tree))!==recipe.ownerSyntaxSha256)fail('owner syntax changed');
 const references=[];
 const protectedNames=new Set(['execFileSync','process','root','path']);
 function visit(node){
  if(ts.isIdentifier(node)&&node.text===recipe.variable)references.push(node);
  if((ts.isVariableDeclaration(node)||ts.isParameter(node)||ts.isFunctionDeclaration(node))&&node.name&&ts.isIdentifier(node.name)&&protectedNames.has(node.name.text))fail('shadowed capability');
  ts.forEachChild(node,visit);
 }
 visit(owner);
 if(references.length!==3)fail('variable reference count');
 const declaration=references[0].parent;
 if(!ts.isVariableDeclaration(declaration)||declaration.name!==references[0]||!ts.isStringLiteral(declaration.initializer)||declaration.initializer.text!==recipe.child)fail('literal declaration');
 const list=declaration.parent,statement=list.parent;
 if(!ts.isVariableDeclarationList(list)||!(list.flags&ts.NodeFlags.Const)||list.declarations.length!==1||statement.parent!==owner.body)fail('same-block const declaration');
 const array=references[1].parent,call=array.parent;
 if(!ts.isArrayLiteralExpression(array)||array.elements[0]!==references[1]||!ts.isCallExpression(call)||call.expression.getText(tree)!=='execFileSync'||call.arguments[0]?.getText(tree)!=='process.execPath'||call.arguments[1]!==array||call.arguments[2]?.getText(tree)!==recipe.optionsSyntax)fail('selected child argv/cwd');
 const callStatement=call.parent?.parent?.parent;
 if(owner.body.statements.indexOf(statement)>=owner.body.statements.indexOf(callStatement))fail('declaration does not precede call');
 const consumer=references[2].parent;
 if(!ts.isCallExpression(consumer)||consumer.expression.getText(tree)!=='objects'||consumer.arguments[0]?.getText(tree)!=='recoveryRendered'||consumer.arguments[1]!==references[2]||consumer.arguments[2]?.getText(tree)!=='namespace')fail('rendered resource consumer');
 acquire(recipe.child);
}

