 assert(recipe&&nativeTest&&word.raw===word.value,`DOCUMENTATION_TOOL_NODE_ENTRY_CUSTODY_UNQUALIFIED: package.json scripts.${name}; unknown/quoted/dynamic native package glob: ${word.raw}`);
