 assert(/^[A-Za-z0-9_./-]+\/\*\.[A-Za-z0-9_.-]+$/u.test(recipe.pattern),`DOCUMENTATION_TOOL_NODE_ENTRY_CUSTODY_UNQUALIFIED: package.json scripts.${name}; malformed finite pattern authority`);
